uniform float flash_rate : 0.0 .. 3.0 = 0.8;
uniform float flash_chance : 0.0 .. 1.0 = 0.25;
uniform float flash_len : 0.05 .. 1.0 = 0.15;
uniform vec3 cloud_col : color = 0.15, 0.18, 0.22;
uniform vec3 flash_col : color = 1.0, 0.95, 0.85;
uniform float cloud_speed : 0.0 .. 2.0 = 0.4;
uniform float cloud_scale : 0.5 .. 6.0 = 2.0;

state float ph;
state float noise_t;
state float bolt_phase;
state float bolt_bright;

void update() {
  ph = fract(ph + dt * flash_rate);
  noise_t = noise_t + dt * cloud_speed * 0.05;
  if (bolt_phase > 0.0) {
    bolt_phase = max(0.0, bolt_phase - dt / flash_len);
  } else if (hash(float(frame) * 37.0) < flash_chance) {
    bolt_phase = 1.0;
  }
  bolt_bright = bolt_phase * bolt_phase;
}

vec3 shade(Led led) {
  fixed x = fixed(led.pos.x);
  fixed y = fixed(led.pos.y);
  fixed z = fixed(led.pos.z);
  fixed t = fixed(noise_t);
  fixed cx = x * fixed(cloud_scale) + t;
  fixed cy = y * fixed(cloud_scale) * fixed(0.7) + t * fixed(1.3);
  fixed cz = z * fixed(cloud_scale) + t * fixed(0.9);
  fixed n1 = sin(cx + sin(cy)) * fixed(0.5);
  fixed n2 = sin(cz + sin(cx * fixed(2.0))) * fixed(0.5);
  fixed cloud = (n1 + n2) * fixed(0.5) + fixed(0.5);
  fixed base = cloud * fixed(0.6) + fixed(0.4);
  fixed bolt = sin(led.s * fixed(20.0) + fixed(bolt_phase) * fixed(6.2832)) * bolt_bright;
  bolt = clamp(bolt, fixed(0.0), fixed(1.0));
  bolt = bolt * bolt;
  fixed lum = base + bolt * fixed(1.5);
  lum = clamp(lum, fixed(0.0), fixed(1.0));
  return hsv2rgb(fixed(0.62), fixed(0.4), lum);
}

